        ['`debug_reset`', 'вход', '+', '+', '+', '`ndmreset` Debug Module; уровень, асинхронный, только с выхода триггера'],
        ['`hart_reset` (в XSTileWrap — `hartResetReq`)', 'вход', '+', 'upstream-порт', 'upstream-порт', '`hartreset` харта; с `EnableCoreReset` сбрасывает только XSCore'],
        ['`core_reset_req`', 'вход', '+', '+', '+', 'запрос контроллера сброса кластера; уровень, асинхронный'],
